// Generate Proposal (OpenAI node) does not pass through input fields,
// so lead_id/research_id/chat_id/company_name/email are read explicitly
// from the trigger — same pattern used throughout Agent 2.
const trigger = $('Execution Trigger by Agent 1').item.json;
const proposal = $json.output[0].content[0].text;

const telegramMessage = `📄 Proposal ready for ${trigger.company_name}

━━━━━━━━━━━━━━━

Subject: ${proposal.subject}

${proposal.body}

━━━━━━━━━━━━━━━

Recipient: ${trigger.email}`;

return {
  lead_id:          trigger.lead_id,
  research_id:      trigger.research_id,
  chat_id:          trigger.chat_id,
  company_name:     trigger.company_name,
  email:            trigger.email,
  subject:          proposal.subject,
  body:             proposal.body,
  kp_text:          `Subject: ${proposal.subject}\n\n${proposal.body}`,
  telegram_message: telegramMessage
};

const trigger = $('Execution Trigger by Agent 1').item.json;
const proposals = $('Query Existing Proposals in Supabase').all().map(i => i.json);
const suppressions = $('Fetch Suppression List from Supabase').all().map(i => i.json);

const alreadySent = proposals.some(r => r.lead_id === trigger.lead_id && r.status === 'sent');

const leadEmail = (trigger.email || '').toLowerCase().trim();
const leadDomain = leadEmail.includes('@') ? leadEmail.split('@')[1] : '';
let suppressed = false;
let suppressReason = '';

for (const entry of suppressions) {
  const sEmail = (entry.email || '').toLowerCase().trim();
  const sDomain = (entry.domain || '').toLowerCase().trim();
  if (sEmail && sEmail === leadEmail) {
    suppressed = true;
    suppressReason = 'email match: ' + entry.reason;
    break;
  }
  if (sDomain && sDomain === leadDomain) {
    suppressed = true;
    suppressReason = 'domain match: ' + entry.reason;
    break;
  }
}

return [{ json: { ...trigger, already_sent: alreadySent, is_suppressed: suppressed, suppress_reason: suppressReason } }];
